package com.canteenconnect.member4.service;
import com.canteenconnect.member4.entity.Feedback;import com.canteenconnect.member4.entity.Rating;import com.canteenconnect.member4.repository.FeedbackRepository;import com.canteenconnect.member4.repository.RatingRepository;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.util.List;
@Service public class FeedbackService {private final FeedbackRepository feedbacks;private final RatingRepository ratings;public FeedbackService(FeedbackRepository f,RatingRepository r){feedbacks=f;ratings=r;}public List<Feedback> getFeedback(){return feedbacks.findAllByOrderBySubmittedAtDesc();}public List<Rating> getRatings(){return ratings.findAllByOrderBySubmittedAtDesc();}@Transactional public Feedback submit(String orderId,String comments,int score){if(orderId==null||orderId.isBlank())throw new IllegalArgumentException("Order ID is required");if(comments==null||comments.isBlank())throw new IllegalArgumentException("Feedback comments are required");if(score<1||score>5)throw new IllegalArgumentException("Rating must be between 1 and 5");Feedback f=feedbacks.save(new Feedback(orderId.trim(),comments.trim()));ratings.save(new Rating(orderId.trim(),score));return f;}}
